CREATE TABLE coord_sessions (workspace_id TEXT NOT NULL,id TEXT NOT NULL,principal_id TEXT NOT NULL,agent_label TEXT NOT NULL,client_kind TEXT NOT NULL,repo TEXT,ttl_seconds INTEGER NOT NULL,expires_at INTEGER NOT NULL,ended INTEGER NOT NULL DEFAULT 0 CHECK(ended IN (0,1)),PRIMARY KEY(workspace_id,id));
CREATE TABLE coord_leases (workspace_id TEXT NOT NULL,issue_id TEXT NOT NULL,project_id TEXT NOT NULL,session_id TEXT,fencing_token INTEGER NOT NULL CHECK(fencing_token>0),expires_at INTEGER NOT NULL,release_reason TEXT,PRIMARY KEY(workspace_id,issue_id));
CREATE TABLE coord_file_claims (workspace_id TEXT NOT NULL,repo TEXT NOT NULL,path TEXT NOT NULL,session_id TEXT NOT NULL,lease_issue_id TEXT,expires_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,repo,path));
CREATE TABLE coord_reports (workspace_id TEXT NOT NULL,issue_id TEXT NOT NULL,session_id TEXT NOT NULL,fencing_token INTEGER NOT NULL,text TEXT NOT NULL,status TEXT NOT NULL,reported_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,issue_id));
CREATE TABLE coord_limits (workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,cap INTEGER NOT NULL CHECK(cap BETWEEN 1 AND 100),version INTEGER NOT NULL CHECK(version>0),PRIMARY KEY(workspace_id,project_id));
CREATE TABLE coord_receipts (workspace_id TEXT NOT NULL,principal_id TEXT NOT NULL,operation_id TEXT NOT NULL,fingerprint TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(workspace_id,principal_id,operation_id));
CREATE TABLE coord_events (workspace_id TEXT NOT NULL,sequence INTEGER NOT NULL,event_id TEXT NOT NULL,type TEXT NOT NULL,subject_id TEXT NOT NULL,actor_id TEXT NOT NULL,other_session_id TEXT,occurred_at INTEGER NOT NULL,PRIMARY KEY(workspace_id,sequence),UNIQUE(workspace_id,event_id));
CREATE TABLE coord_guards (workspace_id TEXT NOT NULL,id TEXT NOT NULL,changed INTEGER NOT NULL CHECK(changed=1),PRIMARY KEY(workspace_id,id));
